UPDATE tenant_administrator_initialization_workflows
SET workflow_state = #{nextState}, next_attempt_at = #{transitionedAt}, last_failure = NULL
WHERE workflow_id = #{workflowId} AND workflow_state = #{expectedState}
  AND lease_owner = #{claimant} AND attempt_count = #{attemptCount}

UPDATE tenant_administrator_initialization_workflows
SET next_attempt_at = #{retryAt}, lease_owner = NULL, lease_until = NULL,
    recovery_exhausted_at = NULL, last_failure = #{lastFailure}
WHERE workflow_id = #{workflowId}
  AND lease_owner = #{claimant} AND attempt_count = #{attemptCount}

UPDATE tenant_administrator_initialization_workflows
SET recovery_exhausted_at = #{exhaustedAt}, lease_owner = NULL, lease_until = NULL,
    last_failure = #{lastFailure}
WHERE workflow_id = #{workflowId}
  AND lease_owner = #{claimant} AND attempt_count = #{attemptCount}

UPDATE tenants SET tenant_status = 'ACTIVE', updated_at = #{updatedAt}
WHERE id = #{tenantId}
  AND tenant_status = 'PENDING'
  AND (expires_at IS NULL OR expires_at > #{updatedAt})
